#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_TERMS 200          /* one more than the allowed 199 */
#define RANGE_LIMIT 100000    /* absolute value limit for the numerator */

int main(int argc, char *argv[])
{
    /* Argument count check – print "NO_INPUT" if not enough args. */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the two arguments with strict checking (exact match). */
    char *endptr;
    errno = 0;
    long num = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    long den = strtol(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range check on the numerator. */
    if (llabs(num) > RANGE_LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Zero denominator – the original program reports "ERROR". */
    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    /* Normalise sign: make denominator positive. */
    if (den < 0) {
        den = -den;
        num = -num;
    }

    /* Compute the continued‑fraction coefficients using the Euclidean algorithm,
       adjusting the quotient when the remainder would be negative. The loop
       stops after 199 terms; exceeding that limit triggers the "ERROR" message. */
    long a = num, b = den;
    long cf[MAX_TERMS];
    int n = 0;                     /* number of stored terms */

    while (b != 0) {
        if (n >= 199) {            /* more than 199 terms → error */
            puts("ERROR");
            return 0;
        }

        long q = a / b;
        long r = a % b;

        /* Adjust to keep the remainder non‑negative. */
        if (r < 0) {
            if (b > 0) {
                q -= 1;
                r += b;
            } else {
                q += 1;
                r -= b;
            }
        }

        cf[n++] = q;
        a = b;
        b = r;
    }

    /* Output the continued fraction in the required format: [a0; a1, a2, …, an] */
    putchar('[');
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            printf("%ld", cf[i]);
        } else if (i == 1) {
            printf("; %ld", cf[i]);
        } else {
            printf(", %ld", cf[i]);
        }
    }
    puts("]");

    return 0;
}
